"""OpenAI Batch API helper module for LangExtract.

This module provides batch inference support using the OpenAI Batch API.
It handles:
- File-based batch submission via the Files API
- Job polling and result extraction
- Order preservation across batch processing using custom IDs
- Job splitting when a batch_size is supplied

The helpers here are provider-agnostic with respect to request shape: the
caller supplies a ``request_builder`` that turns a prompt into the JSON body
of a single ``/v1/chat/completions`` request. This keeps provider-specific
concerns (schema, seed, response_format) in the OpenAI provider itself.
"""

from __future__ import annotations

import collections.abc
import dataclasses
import io
import json
import time
from typing import Any, Callable

from absl import logging

from langextract.core import exceptions

_KEY_IDX = "idx-"
_ENDPOINT = "/v1/chat/completions"
_SUPPORTED_COMPLETION_WINDOWS = frozenset({"24h"})
_TERMINAL_FAIL = frozenset({"failed", "expired", "cancelled"})
_STATUS_COMPLETED = "completed"
_DOWNLOAD_ATTEMPTS = 3


@dataclasses.dataclass
class BatchConfig:
  """Configuration for OpenAI Batch API processing.

  Attributes:
    enabled: Whether batch mode is active.
    threshold: Minimum number of prompts required to trigger batch processing.
    completion_window: Batch completion window. Only '24h' is supported.
    poll_interval: Seconds between job status checks (also used to space out
      retries when downloading output files).
    timeout: Maximum seconds to wait for a job to complete. The default is
      greater than 86400 seconds (more than 24 hours) so it does not expire
      before the completion window.
    max_requests_per_job: Maximum number of requests allowed in a single job.
    metadata: Optional metadata forwarded to the batch creation call.
    on_job_create: Optional callback invoked with each created job object.
  """

  enabled: bool = False
  threshold: int = 10
  completion_window: str = "24h"
  poll_interval: int | float = 30
  timeout: int | float = 90000
  max_requests_per_job: int = 50000
  metadata: dict | None = None
  on_job_create: Callable[[Any], None] | None = None

  def __post_init__(self) -> None:
    """Validate the completion window on construction."""
    if self.completion_window not in _SUPPORTED_COMPLETION_WINDOWS:
      raise ValueError(
          "Unsupported completion_window "
          f"{self.completion_window!r}; only '24h' is supported."
      )

  @classmethod
  def from_dict(cls, obj: Any) -> "BatchConfig":
    """Coerce ``obj`` into a BatchConfig.

    Args:
      obj: A BatchConfig (returned unchanged), a bool (enabling/disabling
        batch mode), None (batch disabled), or a mapping of field values.

    Returns:
      A BatchConfig instance.

    Raises:
      TypeError: If ``obj`` is not one of the supported types (e.g. a list).
    """
    if isinstance(obj, cls):
      return obj
    if obj is None:
      return cls(enabled=False)
    if isinstance(obj, bool):
      return cls(enabled=obj)
    if isinstance(obj, collections.abc.Mapping):
      valid_keys = {f.name for f in dataclasses.fields(cls)}
      filtered = {k: v for k, v in obj.items() if k in valid_keys}
      return cls(**filtered)
    raise TypeError("batch must be a mapping")


def _attr(obj: Any, name: str, default: Any = None) -> Any:
  """Read ``name`` from a mapping or object, returning ``default`` if absent."""
  if isinstance(obj, collections.abc.Mapping):
    return obj.get(name, default)
  return getattr(obj, name, default)


def _errors_text(errors: Any) -> str:
  """Extract human-readable text from a batch job ``errors`` field."""
  data = _attr(errors, "data", None)
  if data is None and isinstance(errors, (list, tuple)):
    data = errors
  if data:
    messages = []
    for item in data:
      message = _attr(item, "message", None)
      messages.append(str(message) if message is not None else str(item))
    return "; ".join(messages)
  return str(errors)


def _raise_terminal(status: str, job: Any) -> None:
  """Raise for a batch job that reached a failing terminal status."""
  message = f"batch job failed: status={status}"
  errors = _attr(job, "errors", None)
  if errors:
    message = f"{message}; errors={_errors_text(errors)}"
  raise exceptions.InferenceRuntimeError(message)


def _content_text(resp: Any) -> str:
  """Extract the text body from a Files.content response."""
  if isinstance(resp, (bytes, bytearray)):
    return resp.decode("utf-8")
  if isinstance(resp, str):
    return resp
  text = getattr(resp, "text", None)
  if isinstance(text, str):
    return text
  content = getattr(resp, "content", None)
  if isinstance(content, (bytes, bytearray)):
    return content.decode("utf-8")
  if isinstance(content, str):
    return content
  read = getattr(resp, "read", None)
  if callable(read):
    data = read()
    if isinstance(data, (bytes, bytearray)):
      return data.decode("utf-8")
    return data
  return str(resp)


def _is_403(error: Exception) -> bool:
  """Return True if ``error`` looks like an HTTP 403 (permission) error."""
  if _attr(error, "status_code", None) == 403:
    return True
  response = getattr(error, "response", None)
  if response is not None and _attr(response, "status_code", None) == 403:
    return True
  return "403" in str(error)


def _download_text(client: Any, file_id: str, cfg: BatchConfig) -> str:
  """Download a batch output/error file, retrying on 403 permission errors."""
  for attempt in range(_DOWNLOAD_ATTEMPTS):
    try:
      return _content_text(client.files.content(file_id))
    except Exception as e:  # pylint: disable=broad-except
      if _is_403(e):
        if attempt < _DOWNLOAD_ATTEMPTS - 1:
          logging.warning(
              "403 downloading batch file %s (attempt %d/%d); retrying.",
              file_id,
              attempt + 1,
              _DOWNLOAD_ATTEMPTS,
          )
          time.sleep(cfg.poll_interval)
          continue
        raise exceptions.InferenceRuntimeError(
            "Failed to download batch file after "
            f"{_DOWNLOAD_ATTEMPTS} attempts: the API key is missing the "
            "'Files Read' permission (HTTP 403).",
            original=e,
        ) from e
      raise
  # Unreachable: the loop either returns or raises.
  raise exceptions.InferenceRuntimeError(  # pragma: no cover
      f"Failed to download batch file {file_id}"
  )


def _idx_from_custom_id(custom_id: str) -> int:
  """Recover the original prompt index from a custom_id like 'idx-000003'."""
  return int(str(custom_id).rsplit(_KEY_IDX, maxsplit=1)[-1])


